    probe = (obs.get(lv) or {}).get("fault") or {}
    p = probe.get("path")
    if not p:
        return None
    fp = Path(p)
    if not fp.is_absolute():
        fp = Path(d) / fp
    if not fp.exists():
        cand = Path(d) / Path(p).name
        if cand.exists():
            return cand
    return fp if fp.exists() else None


